#include <iostream>
#include <vector>
#include <array>
#include "../earcut.hpp"

int main(int argc, char* argv[]) {
    int n = 1;
    if (argc > 1) {
        n = std::atoi(argv[1]);
    }

    std::vector<std::vector<std::array<double, 2>>> polygon;
    std::vector<std::array<double, 2>> ring;

    for (int i = 0; i < n * 3; i++) {
        double angle = 2.0 * M_PI * i / (n * 3);
        ring.push_back({std::cos(angle), std::sin(angle)});
    }
    polygon.push_back(ring);

    auto indices = mapbox::earcut<uint32_t>(polygon);

    for (auto idx : indices) {
        std::cout << idx << " ";
    }
    return 0;
}


