    diff <(timeout 120 "$REF" "${a[@]}" | tr ' ' '\n') <(timeout 120 "$CAND" "${a[@]}" | tr ' ' '\n') | head -12
  fi
done < /tmp/gt/args.txt
echo "RESULT: pass=$pass fail=$fail"
[ "$fail" -eq 0 ] && echo "ALL_TESTS_PASSED" || echo "TESTS_FAILED"

