//! Arena-backed doubly-linked-list node model.
//!
//! This replaces earcut.hpp's `Node*` / `ObjectPool<Node>` with an append-only
//! `Vec<Node>` plus `usize` handles. `NIL` (== `usize::MAX`) plays the role of
//! `nullptr`. Because the arena is append-only, a `NodeId` behaves exactly like
//! a raw pointer that is never freed -- which is precisely the lifetime model
//! the C++ relies on (its pool frees nothing until destruction).
//!
//! No `unsafe`, no `Rc`, no `RefCell`.

/// The "nullptr" sentinel.
pub const NIL: usize = usize::MAX;

/// A handle into [`Earcut::arena`].
pub type NodeId = usize;

/// A 2D point, mirroring C++'s `std::array<double, 2>`.
pub type Pt = [f64; 2];

pub struct Node {
    /// Vertex index in the original coordinate stream (reported in the output).
    pub i: u32,
    pub x: f64,
    pub y: f64,
    /// Previous node in the ring. Always a valid handle after `insert_node`.
    pub prev: NodeId,
    /// Next node in the ring. Always a valid handle after `insert_node`.
    pub next: NodeId,
    /// z-order curve value; `0` means "not yet computed" (memoization sentinel).
    pub z: i32,
    /// Previous node in the z-order chain (NIL-able).
    pub prev_z: NodeId,
    /// Next node in the z-order chain (NIL-able).
    pub next_z: NodeId,
    /// Indicates whether this is a Steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Node {
        Node {
            i: i,
            x: x,
            y: y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

/// The whole triangulator state; the analogue of C++'s `mapbox::detail::Earcut<N>`.
pub struct Earcut {
    /// Append-only node storage. Nothing is EVER removed from this vector:
    /// `remove_node` only unlinks, and stale `prev`/`next` links on removed
    /// nodes are load-bearing (see `filter_points`, `cure_local_intersections`).
    pub arena: Vec<Node>,
    /// The output triangle index list.
    pub indices: Vec<u32>,
    /// Running vertex-index offset across rings.
    pub vertices: usize,
    pub hashing: bool,
    pub min_x: f64,
    pub min_y: f64,
    pub max_x: f64,
    pub max_y: f64,
    pub inv_size: f64,
}

impl Earcut {
    pub fn new() -> Earcut {
        Earcut {
            arena: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            max_x: 0.0,
            max_y: 0.0,
            inv_size: 0.0,
        }
    }

    // ---- tiny copy accessors -------------------------------------------------
    // Never hold a `&mut Node` across a call to another `&mut self` method;
    // read what you need into locals first, then mutate with single-statement
    // indexed assignments.

    #[inline]
    pub fn x(&self, p: NodeId) -> f64 {
        self.arena[p].x
    }
    #[inline]
    pub fn y(&self, p: NodeId) -> f64 {
        self.arena[p].y
    }
    #[inline]
    pub fn idx(&self, p: NodeId) -> u32 {
        self.arena[p].i
    }
    #[inline]
    pub fn pv(&self, p: NodeId) -> NodeId {
        self.arena[p].prev
    }
    #[inline]
    pub fn nx(&self, p: NodeId) -> NodeId {
        self.arena[p].next
    }
    #[inline]
    pub fn pz(&self, p: NodeId) -> NodeId {
        self.arena[p].prev_z
    }
    #[inline]
    pub fn nz(&self, p: NodeId) -> NodeId {
        self.arena[p].next_z
    }
    #[inline]
    pub fn zz(&self, p: NodeId) -> i32 {
        self.arena[p].z
    }

    /// `mapbox::detail::Earcut::insertNode` -- create a node and optionally
    /// splice it into the ring right after `last`.
    pub fn insert_node(&mut self, i: usize, px: f64, py: f64, last: NodeId) -> NodeId {
        let p = self.arena.len();
        self.arena.push(Node::new(i as u32, px, py));

        if last == NIL {
            // First node of a fresh ring: a self-loop.
            self.arena[p].prev = p;
            self.arena[p].next = p;
        } else {
            let ln = self.arena[last].next;
            self.arena[p].next = ln;
            self.arena[p].prev = last;
            self.arena[ln].prev = p;
            self.arena[last].next = p;
        }
        p
    }

    /// `mapbox::detail::Earcut::removeNode` -- unlink `p` from the ring and the
    /// z-order chain.
    ///
    /// This deliberately does NOT clear `p`'s own `prev`/`next`/`prev_z`/`next_z`
    /// fields, and never removes the entry from the arena. `filter_points` does
    /// `remove_node(p); p = p.prev;` and `cure_local_intersections` does
    /// `remove_node(p); remove_node(p.next);` -- both read the STALE links of a
    /// node that was just unlinked. Self-removal (a 1-element self-looped ring)
    /// is a harmless no-op under these writes.
    pub fn remove_node(&mut self, p: NodeId) {
        let pp = self.arena[p].prev;
        let pn = self.arena[p].next;

        self.arena[pn].prev = pp;
        self.arena[pp].next = pn;

        let pz = self.arena[p].prev_z;
        let nz = self.arena[p].next_z;
        if pz != NIL {
            self.arena[pz].next_z = nz;
        }
        if nz != NIL {
            self.arena[nz].prev_z = pz;
        }
    }

    /// `mapbox::detail::Earcut::equals` -- exact f64 coordinate equality.
    /// No epsilon, no `total_cmp`.
    #[inline]
    pub fn equals(&self, p1: NodeId, p2: NodeId) -> bool {
        self.arena[p1].x == self.arena[p2].x && self.arena[p1].y == self.arena[p2].y
    }
}

//! Geometric predicates -- a term-for-term port of the free/member predicate
//! functions in earcut.hpp.
//!
//! Every comparison operator here is load-bearing. `>=` vs `>` decides whether
//! collinear triples are accepted, and the asymmetry between `locally_inside`'s
//! two branches (AND/inclusive vs OR/strict) is intentional upstream.

use crate::node::{Earcut, NodeId};

/// Signed doubled area of the triangle (p, q, r).
///
/// NEGATIVE means "convex" for the CCW winding earcut normalizes to.
#[inline]
pub fn area_of(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}

/// `mapbox::detail::Earcut::sign`
#[inline]
pub fn sign(val: f64) -> i32 {
    if val > 0.0 {
        1
    } else if val < 0.0 {
        -1
    } else {
        0
    }
}

/// `mapbox::detail::Earcut::pointInTriangle` -- all three tests are INCLUSIVE,
/// so a point exactly on an edge or at a vertex counts as inside.
#[allow(clippy::too_many_arguments)]
#[inline]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

impl Earcut {
    /// `area(p, q, r)` over node handles.
    #[inline]
    pub fn area(&self, p: NodeId, q: NodeId, r: NodeId) -> f64 {
        let px = self.x(p);
        let py = self.y(p);
        let qx = self.x(q);
        let qy = self.y(q);
        let rx = self.x(r);
        let ry = self.y(r);
        area_of(px, py, qx, qy, rx, ry)
    }

    /// `mapbox::detail::Earcut::onSegment` -- is `q` inside the bbox spanned by
    /// `p` and `r`?
    pub fn on_segment(&self, p: NodeId, q: NodeId, r: NodeId) -> bool {
        let px = self.x(p);
        let py = self.y(p);
        let qx = self.x(q);
        let qy = self.y(q);
        let rx = self.x(r);
        let ry = self.y(r);
        qx <= f64::max(px, rx)
            && qx >= f64::min(px, rx)
            && qy <= f64::max(py, ry)
            && qy >= f64::min(py, ry)
    }

    /// `mapbox::detail::Earcut::intersects` -- do segments (p1,q1) and (p2,q2)
    /// intersect? Handles the collinear/touching cases in the upstream order.
    pub fn intersects(&self, p1: NodeId, q1: NodeId, p2: NodeId, q2: NodeId) -> bool {
        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            // general case
            return true;
        }
        if o1 == 0 && self.on_segment(p1, p2, q1) {
            // p1, q1 and p2 are collinear and p2 lies on p1q1
            return true;
        }
        if o2 == 0 && self.on_segment(p1, q2, q1) {
            // p1, q1 and q2 are collinear and q2 lies on p1q1
            return true;
        }
        if o3 == 0 && self.on_segment(p2, p1, q2) {
            // p2, q2 and p1 are collinear and p1 lies on p2q2
            return true;
        }
        if o4 == 0 && self.on_segment(p2, q1, q2) {
            // p2, q2 and q1 are collinear and q1 lies on p2q2
            return true;
        }
        false
    }

    /// `mapbox::detail::Earcut::intersectsPolygon` -- does the polygon edge ring
    /// intersect the candidate diagonal (a, b)?
    ///
    /// NOTE: compares `.i` values, not node handles, because `split_polygon`
    /// mints clones that share an `.i` and must count as the same vertex.
    pub fn intersects_polygon(&self, a: NodeId, b: NodeId) -> bool {
        let ai = self.idx(a);
        let bi = self.idx(b);
        let mut p = a;
        loop {
            let pn = self.nx(p);
            let pi = self.idx(p);
            let pni = self.idx(pn);
            if pi != ai && pni != ai && pi != bi && pni != bi && self.intersects(p, pn, a, b) {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    /// `mapbox::detail::Earcut::locallyInside` -- is the diagonal (a, b) locally
    /// inside the polygon at vertex `a`?
    ///
    /// The two branches are deliberately asymmetric: convex uses AND/inclusive,
    /// reflex uses OR/strict.
    pub fn locally_inside(&self, a: NodeId, b: NodeId) -> bool {
        let ap = self.pv(a);
        let an = self.nx(a);
        if self.area(ap, a, an) < 0.0 {
            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
        } else {
            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
        }
    }

    /// `mapbox::detail::Earcut::middleInside` -- ray-cast the midpoint of (a, b)
    /// against the ring containing `a`.
    pub fn middle_inside(&self, a: NodeId, b: NodeId) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let pn = self.nx(p);
            let pyv = self.y(p);
            let pny = self.y(pn);
            // The `pny != pyv` guard prevents a 0/0 NaN in the division below.
            if ((pyv > py) != (pny > py))
                && pny != pyv
                && (px < (self.x(pn) - self.x(p)) * (py - pyv) / (pny - pyv) + self.x(p))
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    /// `mapbox::detail::Earcut::isValidDiagonal` -- is (a, b) a valid diagonal
    /// that splits the polygon into two well-formed halves?
    pub fn is_valid_diagonal(&self, a: NodeId, b: NodeId) -> bool {
        let an = self.nx(a);
        let ap = self.pv(a);
        let bp = self.pv(b);
        let bn = self.nx(b);
        let bi = self.idx(b);

        self.idx(an) != bi
            && self.idx(ap) != bi
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                // does not create opposite-facing sectors
                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
                // special zero-length case
                || (self.equals(a, b)
                    && self.area(ap, a, an) > 0.0
                    && self.area(bp, b, bn) > 0.0))
    }

    /// `mapbox::detail::Earcut::sectorContainsSector` -- whether sector in vertex
    /// m contains sector in vertex p, in the same coordinates.
    pub fn sector_contains_sector(&self, m: NodeId, p: NodeId) -> bool {
        let mp = self.pv(m);
        let mn = self.nx(m);
        let pp = self.pv(p);
        let pn = self.nx(p);
        self.area(mp, m, pp) < 0.0 && self.area(pn, m, mn) < 0.0
    }
}

//! z-order (Morton) curve machinery: `zOrder`, `indexCurve`, `sortLinked`.
//!
//! Enabled only when the total point count exceeds 80. It changes *which*
//! point-in-triangle candidates get scanned (turning the ear test from O(n)
//! into roughly O(1)), and must never change the emitted triangles.

use crate::node::{Earcut, NodeId, NIL};

impl Earcut {
    /// `mapbox::detail::Earcut::zOrder` -- interleave the low 15 bits of the
    /// quantized x and y coordinates into a 30-bit Morton code.
    pub fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x: i32 = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y: i32 = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    /// `mapbox::detail::Earcut::indexCurve` -- interlink the ring's nodes in
    /// z-order.
    ///
    /// The sorted head returned by `sort_linked` is deliberately DISCARDED:
    /// `is_ear_hashed` only ever navigates outward from `ear` via
    /// `prev_z`/`next_z`, so no head handle is needed (and keeping one would
    /// only invite staleness after removals).
    pub fn index_curve(&mut self, start: NodeId) {
        let mut p = start;
        loop {
            if self.arena[p].z == 0 {
                let px = self.x(p);
                let py = self.y(p);
                let z = self.z_order(px, py);
                self.arena[p].z = z;
            }
            let pp = self.arena[p].prev;
            let pn = self.arena[p].next;
            self.arena[p].prev_z = pp;
            self.arena[p].next_z = pn;
            p = pn;
            if p == start {
                break;
            }
        }

        // Cut the circular z chain open into a linear one.
        let pz = self.arena[p].prev_z;
        self.arena[pz].next_z = NIL;
        self.arena[p].prev_z = NIL;

        self.sort_linked(p);
    }

    /// `mapbox::detail::Earcut::sortLinked` -- Simon Tatham's iterative
    /// bottom-up merge sort on a doubly-linked list, keyed on `z`.
    ///
    /// The `<=` in the merge comparison keeps the sort STABLE; equal-z nodes are
    /// common (the grid is only 15 bits per axis) and an unstable merge would
    /// permute their prev_z/next_z neighbours and hence the ear-scan order.
    pub fn sort_linked(&mut self, list0: NodeId) -> NodeId {
        let mut list = list0;
        let mut in_size: i32 = 1;

        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut num_merges = 0;

            while p != NIL {
                num_merges += 1;
                let mut q = p;
                let mut p_size: i32 = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.arena[q].next_z;
                    if q == NIL {
                        break;
                    }
                }

                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q != NIL) {
                    let e;
                    if p_size == 0 {
                        e = q;
                        q = self.arena[q].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q == NIL {
                        e = p;
                        p = self.arena[p].next_z;
                        p_size -= 1;
                    } else if self.zz(p) <= self.zz(q) {
                        e = p;
                        p = self.arena[p].next_z;
                        p_size -= 1;
                    } else {
                        e = q;
                        q = self.arena[q].next_z;
                        q_size -= 1;
                    }

                    if tail != NIL {
                        self.arena[tail].next_z = e;
                    } else {
                        list = e;
                    }

                    self.arena[e].prev_z = tail;
                    tail = e;
                }

                p = q;
            }

            if tail != NIL {
                self.arena[tail].next_z = NIL;
            }

            if num_merges <= 1 {
                return list;
            }

            in_size *= 2;
        }
    }
}

//! Ring construction and mutation: `linkedList`, `filterPoints`, `splitPolygon`,
//! and the whole hole-elimination pipeline (`eliminateHoles`, `eliminateHole`,
//! `findHoleBridge`, `getLeftmost`).
//!
//! The hole pipeline is unreachable from the test1 driver (a single ring), but is
//! ported in full for fidelity.

use crate::node::{Earcut, NodeId, Node, Pt, NIL};
use crate::predicates::point_in_triangle;

impl Earcut {
    /// `mapbox::detail::Earcut::linkedList` -- create a circular doubly-linked
    /// list from the polygon points, in the specified winding order.
    ///
    /// Returns the LAST INSERTED node (or `NIL` for an empty ring). For forward
    /// insertion that is vertex `len-1`; for reverse insertion it is vertex `0`.
    /// Never reconstruct the start node from `len`.
    pub fn linked_list(&mut self, points: &[Pt], clockwise: bool) -> NodeId {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut last: NodeId = NIL;

        // calculate original winding order of a polygon ring
        // (C: for (i = 0, j = len - 1; i < len; j = i++))
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i]; // current
            let p2 = points[j]; // previous
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into circular doubly-linked list in the specified winding order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i][0], points[i][1], last);
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = self.insert_node(self.vertices + i, points[i][0], points[i][1], last);
            }
        }

        if last != NIL {
            let ln = self.nx(last);
            if self.equals(last, ln) {
                self.remove_node(last);
                last = ln;
            }
        }

        self.vertices += len;

        last
    }

    /// `mapbox::detail::Earcut::filterPoints` -- eliminate colinear or duplicate
    /// points. `end0 == NIL` stands for C++'s defaulted `nullptr` argument,
    /// meaning "default to `start`".
    pub fn filter_points(&mut self, start: NodeId, end0: NodeId) -> NodeId {
        if start == NIL {
            return NIL;
        }

        let mut end = if end0 == NIL { start } else { end0 };

        let mut p = start;
        loop {
            let mut again = false;

            let pn = self.nx(p);
            let pp = self.pv(p);
            if !self.arena[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
                self.remove_node(p);
                // Reads the STALE `prev` of the node just unlinked -- by design.
                p = self.pv(p);
                end = p;
                if p == self.nx(p) {
                    break;
                }
                again = true;
            } else {
                p = self.nx(p);
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// `mapbox::detail::Earcut::splitPolygon` -- link two polygon vertices with a
    /// bridge; if the vertices belong to the same ring, it splits the polygon
    /// into two, and if one belongs to the outer ring and another to a hole, it
    /// merges it into a single ring.
    ///
    /// Mints two brand-new arena nodes that duplicate `a`'s and `b`'s `i`/`x`/`y`.
    /// The duplicated `.i` is intentional -- that is why `intersects_polygon`,
    /// `is_valid_diagonal` and `split_earcut` compare `.i` rather than handles.
    pub fn split_polygon(&mut self, a: NodeId, b: NodeId) -> NodeId {
        let ai = self.idx(a);
        let ax = self.x(a);
        let ay = self.y(a);
        let bi = self.idx(b);
        let bx = self.x(b);
        let by = self.y(b);

        let a2 = self.arena.len();
        self.arena.push(Node::new(ai, ax, ay));
        let b2 = self.arena.len();
        self.arena.push(Node::new(bi, bx, by));

        let an = self.nx(a);
        let bp = self.pv(b);

        self.arena[a].next = b;
        self.arena[b].prev = a;

        self.arena[a2].next = an;
        self.arena[an].prev = a2;

        self.arena[b2].next = a2;
        self.arena[a2].prev = b2;

        self.arena[bp].next = b2;
        self.arena[b2].prev = bp;

        b2
    }

    /// `mapbox::detail::Earcut::getLeftmost` -- find the leftmost node of a ring
    /// (ties broken by the lower y).
    pub fn get_leftmost(&self, start: NodeId) -> NodeId {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.x(p) < self.x(leftmost)
                || (self.x(p) == self.x(leftmost) && self.y(p) < self.y(leftmost))
            {
                leftmost = p;
            }
            p = self.nx(p);
            if p == start {
                break;
            }
        }
        leftmost
    }

    /// `mapbox::detail::Earcut::eliminateHoles` -- link every hole into the outer
    /// loop, producing a single-ring polygon without holes.
    pub fn eliminate_holes(&mut self, polygon: &[Vec<Pt>], outer_node0: NodeId) -> NodeId {
        let mut outer_node = outer_node0;
        let len = polygon.len();

        let mut queue: Vec<NodeId> = Vec::new();
        for i in 1..len {
            // Holes are built with the OPPOSITE winding from the outer ring.
            let list = self.linked_list(&polygon[i], false);
            if list != NIL {
                if list == self.nx(list) {
                    self.arena[list].steiner = true;
                }
                let lm = self.get_leftmost(list);
                queue.push(lm);
            }
        }

        // Sort on x ONLY (get_leftmost already broke y ties per hole). libstdc++
        // uses an UNSTABLE introsort here, so ties among distinct holes sharing a
        // leftmost x are an accepted, unobservable-for-this-driver divergence.
        {
            // Avoid closure-capture borrow conflicts by snapshotting the keys.
            let mut keyed: Vec<(f64, NodeId)> =
                queue.iter().map(|&n| (self.x(n), n)).collect();
            keyed.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
            queue = keyed.iter().map(|kv| kv.1).collect();
        }

        // process holes from left to right
        for i in 0..queue.len() {
            outer_node = self.eliminate_hole(queue[i], outer_node);
        }

        outer_node
    }

    /// `mapbox::detail::Earcut::eliminateHole` -- find a bridge between the
    /// vertices of a hole and the outer ring and link it.
    pub fn eliminate_hole(&mut self, hole: NodeId, outer_node: NodeId) -> NodeId {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let brn = self.nx(bridge_reverse);
        self.filter_points(bridge_reverse, brn);
        let bn = self.nx(bridge);
        self.filter_points(bridge, bn)
    }

    /// `mapbox::detail::Earcut::findHoleBridge` -- David Eberly's algorithm for
    /// finding a bridge between a hole and an outer ring.
    pub fn find_hole_bridge(&self, hole: NodeId, outer_node: NodeId) -> NodeId {
        let mut p = outer_node;
        let hx = self.x(hole);
        let hy = self.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m: NodeId = NIL;

        // find a segment intersected by a ray from the hole's leftmost Vertex to
        // the left; segment's endpoint with lesser x will be potential connection
        // Vertex
        loop {
            let pn = self.nx(p);
            let py = self.y(p);
            let pny = self.y(pn);
            if hy <= py && hy >= pny && pny != py {
                let px = self.x(p);
                let pnx = self.x(pn);
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    m = if px < pnx { p } else { pn };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole Vertex, segment
        // intersection and endpoint; if there are no points found, we have a
        // valid connection; otherwise choose the Vertex of the minimum angle with
        // the ray as connection Vertex

        let stop = m;
        // mx/my are captured ONCE from the initial m and are deliberately NOT
        // refreshed when m is reassigned below (faithful to upstream).
        let mx = self.x(m);
        let my = self.y(m);
        let mut tan_min = f64::INFINITY;

        p = m;
        loop {
            let px = self.x(p);
            let py = self.y(p);
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = f64::abs(hy - py) / (hx - px); // tangential

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.x(m) || self.sector_contains_sector(m, p))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nx(p);
            if p == stop {
                break;
            }
        }

        m
    }
}

