//! The ear-clipping sweep: `earcutLinked`, `isEar`, `isEarHashed`,
//! `cureLocalIntersections`, `splitEarcut`, plus the top-level `operator()`.

use crate::node::{Earcut, NodeId, Pt, NIL};
use crate::predicates::point_in_triangle;

impl Earcut {
    /// `mapbox::detail::Earcut::earcutLinked` -- main ear slicing loop which
    /// triangulates a polygon (given as a linked list).
    pub fn earcut_linked(&mut self, ear0: NodeId, pass: i32) {
        if ear0 == NIL {
            return;
        }
        let mut ear = ear0;

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.pv(ear) != self.nx(ear) {
            let prev = self.pv(ear);
            let next = self.nx(ear);

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                let a = self.idx(prev);
                let b = self.idx(ear);
                let c = self.idx(next);
                self.indices.push(a);
                self.indices.push(b);
                self.indices.push(c);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nx(next);
                stop = self.nx(next);

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any
            // more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let f = self.filter_points(ear, NIL);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small
                    // self-intersections locally
                    let f = self.filter_points(ear, NIL);
                    let e2 = self.cure_local_intersections(f);
                    self.earcut_linked(e2, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon
                    // into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// `mapbox::detail::Earcut::isEar` -- check whether a polygon node forms a
    /// valid ear with adjacent nodes (linear scan variant).
    pub fn is_ear(&self, ear: NodeId) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);

        if self.area(a, b, c) >= 0.0 {
            // reflex, can't be an ear
            return false;
        }

        let ax = self.x(a);
        let ay = self.y(a);
        let bx = self.x(b);
        let by = self.y(b);
        let cx = self.x(c);
        let cy = self.y(c);

        // now make sure we don't have other points inside the potential ear.
        // The scan range structurally excludes a, b and c, so no identity checks
        // are needed.
        let mut p = self.nx(self.nx(ear));

        while p != self.pv(ear) {
            let px = self.x(p);
            let py = self.y(p);
            if point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.nx(p);
        }

        true
    }

    /// `mapbox::detail::Earcut::isEarHashed` -- ear test restricted to the
    /// candidates whose Morton code falls inside the ear triangle's bbox range.
    pub fn is_ear_hashed(&self, ear: NodeId) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);

        if self.area(a, b, c) >= 0.0 {
            // reflex, can't be an ear
            return false;
        }

        let ax = self.x(a);
        let ay = self.y(a);
        let bx = self.x(b);
        let by = self.y(b);
        let cx = self.x(c);
        let cy = self.y(c);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = f64::min(ax, f64::min(bx, cx));
        let min_ty = f64::min(ay, f64::min(by, cy));
        let max_tx = f64::max(ax, f64::max(bx, cx));
        let max_ty = f64::max(ay, f64::max(by, cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.pz(ear);
        let mut n = self.nz(ear);

        while p != NIL && self.zz(p) >= min_z && n != NIL && self.zz(n) <= max_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.pz(p);

            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0
            {
                return false;
            }
            n = self.nz(n);
        }

        // look for remaining points in decreasing z-order
        while p != NIL && self.zz(p) >= min_z {
            if p != a
                && p != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0
            {
                return false;
            }
            p = self.pz(p);
        }

        // look for remaining points in increasing z-order
        while n != NIL && self.zz(n) <= max_z {
            if n != a
                && n != c
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0
            {
                return false;
            }
            n = self.nz(n);
        }

        true
    }

    /// `mapbox::detail::Earcut::cureLocalIntersections` -- go through all polygon
    /// nodes and cure small local self-intersections.
    pub fn cure_local_intersections(&mut self, start0: NodeId) -> NodeId {
        let mut start = start0;
        let mut p = start;
        loop {
            let a = self.pv(p);
            let pn = self.nx(p);
            let b = self.nx(pn);

            if !self.equals(a, b)
                && self.intersects(a, p, pn, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                let ia = self.idx(a);
                let ip = self.idx(p);
                let ib = self.idx(b);
                self.indices.push(ia);
                self.indices.push(ip);
                self.indices.push(ib);

                // remove two nodes involved
                self.remove_node(p);
                // reads p's STALE `next` -- by design
                let pn2 = self.nx(p);
                self.remove_node(pn2);

                p = b;
                start = b;
            }

            p = self.nx(p);
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// `mapbox::detail::Earcut::splitEarcut` -- try splitting polygon into two and
    /// triangulate them independently.
    pub fn split_earcut(&mut self, start: NodeId) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nx(self.nx(a));
            while b != self.pv(a) {
                if self.idx(a) != self.idx(b) && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.nx(a);
                    a = self.filter_points(a, an);
                    let cn = self.nx(c);
                    c = self.filter_points(c, cn);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nx(b);
            }
            a = self.nx(a);
            if a == start {
                break;
            }
        }
    }

    /// `mapbox::detail::Earcut::operator()` -- the top-level driver.
    pub fn run(&mut self, polygon: &[Vec<Pt>]) {
        // reset
        self.indices.clear();
        self.vertices = 0;

        if polygon.is_empty() {
            return;
        }

        let mut threshold: i32 = 80;
        let mut len: usize = 0;

        let mut i = 0usize;
        while threshold >= 0 && i < polygon.len() {
            threshold -= polygon[i].len() as i32;
            len += polygon[i].len();
            i += 1;
        }

        // estimate size of nodes and indices (capacity hints only; these must
        // never change behaviour, hence the saturating arithmetic)
        self.arena
            .reserve((len * 3 / 2).saturating_sub(polygon[0].len() / 2));
        self.indices.reserve(len.saturating_add(polygon[0].len()));

        let mut outer_node = self.linked_list(&polygon[0], true);
        if outer_node == NIL || self.pv(outer_node) == self.nx(outer_node) {
            return;
        }

        if polygon.len() > 1 {
            outer_node = self.eliminate_holes(polygon, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nx(outer_node);
            self.min_x = self.x(outer_node);
            self.max_x = self.min_x;
            self.min_y = self.y(outer_node);
            self.max_y = self.min_y;
            loop {
                let x = self.x(p);
                let y = self.y(p);
                if x < self.min_x {
                    self.min_x = x;
                }
                if y < self.min_y {
                    self.min_y = y;
                }
                if x > self.max_x {
                    self.max_x = x;
                }
                if y > self.max_y {
                    self.max_y = y;
                }
                p = self.nx(p);
                if p == outer_node {
                    break;
                }
            }

            // minX, minY and size are later used to transform coords into
            // integers for z-order calculation
            let mut inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
            inv_size = if inv_size != 0.0 {
                32767.0 / inv_size
            } else {
                0.0
            };
            self.inv_size = inv_size;
        }

        self.earcut_linked(outer_node, 0);
    }
}

/// `mapbox::earcut<uint32_t>(polygon)` -- the public entry point.
pub fn earcut(polygon: &[Vec<Pt>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices
}
